    // header-only chain still yields ONE (empty) segment so the ledger
    // schema stays stable.
    if (pending case final summary?) {
      segments.lastOrNull?.requests.add(summary.fallback());
      pending = null;
    }
    if (segments.isEmpty) segments.add(_ScanSegment());
