  // freed window was never used.
  final lastMessage = _agent.state.messages.lastOrNull;
  final finished = await _settleAfterPrompt(
    lastMessage,
    isAutoContinue: false,
  );
  // Awaits any in-flight TTSR retry chain, persists the messages, and
