    byModel: usageByModelFromJson(json['byModel']),
    source: UsageSource.parse(json['source'] as String?),
    openedAt: DateTime.tryParse(json['openedAt'] as String? ?? ''),
    closedAt: DateTime.tryParse(json['closedAt'] as String? ?? ''),
